import os
import requests

BASE_URL = "https://api.spotify.com/v1"
headers = {"Authorization": f"Bearer {os.environ['SPOTIFY_ACCESS_TOKEN']}"}

current_response = requests.get(
    f"{BASE_URL}/me/player/currently-playing",
    headers=headers,
)
current_response.raise_for_status()
current = current_response.json()

track = current.get("item")
if not track:
    raise RuntimeError("No track is currently playing.")

artist_ids = [
    artist["id"]
    for artist in track.get("artists", [])
    if artist.get("id")
]
if not artist_ids:
    raise RuntimeError("The currently playing track has no artist IDs.")

artist_response = requests.get(
    f"{BASE_URL}/artists/{artist_ids[0]}",
    headers=headers,
)
artist_response.raise_for_status()
genres = artist_response.json().get("genres", [])
if not genres:
    raise RuntimeError("Could not determine the currently playing artist's genres.")

recommendations_response = requests.get(
    f"{BASE_URL}/recommendations",
    headers=headers,
    params={
        "seed_artists": artist_ids[0],
        "seed_genres": ",".join(genres[:5]),
        "seed_tracks": track["id"],
        "limit": 10,
    },
)
recommendations_response.raise_for_status()

for recommended_track in recommendations_response.json().get("tracks", []):
    artists = ", ".join(artist["name"] for artist in recommended_track.get("artists", []))
    print(f"{recommended_track['name']} — {artists}")

